/** Local provider identity assets. Sources and licenses: assets/providers/README.md. */
export type ProviderBrandId = 'netflix' | 'prime' | 'disney' | 'apple' | 'now' | 'paramount' | 'bbc' | 'itvx' | 'channel4';

export interface ProviderBrand {
  id: ProviderBrandId;
  name: string;
  accent: string;
  /** Self-contained image source; provider tiles never need a third-party request. */
  logo: string;
}

const svg = (source: string): string => `data:image/svg+xml,${encodeURIComponent(source)}`;

